import React, { useState, useEffect } from 'react';
import type { StairElement } from '../../core/types';
interface Props {
  element: StairElement | null;
    onUpdate: (id: string, patch: Partial<StairElement>) => void;
      onRotate: (id: string) => void;
        onDelete: (id: string) => void;
        }
        const inputStyle: React.CSSProperties = {
          width: '70px',
            padding: '6px 8px',
              borderRadius: 6,
                border: '1px solid #ccc',
                  fontSize: 14,
                    textAlign: 'center',
                      direction: 'ltr',
                      };
                      const labelStyle: React.CSSProperties = { fontWeight: 700, fontSize: 13, color: '#003366' };
                      const safeNum = (v: string, fb: number) => {
                        const n = parseFloat(v.replace(',', '.'));
                          return isNaN(n) ? fb : n;
                          };
                          export const StairElementProperties: React.FC<Props> = ({ element, onUpdate, onRotate, onDelete }) => {
                            const [lengthStr, setLengthStr] = useState('');
                              const [widthStr, setWidthStr] = useState('');
                                const [treadStr, setTreadStr] = useState('');
                                  const [riserStr, setRiserStr] = useState('');
                                    const [elevStr, setElevStr] = useState('');
                                      useEffect(() => {
                                          if (element) {
                                                setLengthStr(element.length.toFixed(2));
                                                      setWidthStr(element.width.toFixed(2));
                                                            setElevStr((element.elevation ?? 0).toFixed(2));
                                                                  if (element.type === 'step') {
                                                                          setTreadStr((element.treadDepth ?? 0.27).toFixed(2));
                                                                                  setRiserStr((element.riserHeight ?? 0.17).toFixed(2));
                                                                                        }
                                                                                            }
                                                                                              }, [element]);
                                                                                                if (!element) return null;
                                                                                                  const commitLength = () => {
                                                                                                      const v = safeNum(lengthStr, element.length);
                                                                                                          if (v > 0) {
                                                                                                                const td = element.treadDepth ?? 0.27;
                                                                                                                      const newStepCount = Math.max(2, Math.floor(v / td));
                                                                                                                            onUpdate(element.id, { length: v, stepCount: newStepCount });
                                                                                                                                } else {
                                                                                                                                      setLengthStr(element.length.toFixed(2));
                                                                                                                                          }
                                                                                                                                            };
                                                                                                                                              const commitWidth = () => {
                                                                                                                                                  const v = safeNum(widthStr, element.width);
                                                                                                                                                      if (v > 0) onUpdate(element.id, { width: v });
                                                                                                                                                          else setWidthStr(element.width.toFixed(2));
                                                                                                                                                            };
                                                                                                                                                              const commitTread = () => {
                                                                                                                                                                  const v = safeNum(treadStr, element.treadDepth ?? 0.27);
                                                                                                                                                                      if (v > 0) {
                                                                                                                                                                            const stepCount = Math.max(2, Math.floor(element.length / v));
                                                                                                                                                                                  onUpdate(element.id, { treadDepth: v, stepCount });
                                                                                                                                                                                      } else setTreadStr((element.treadDepth ?? 0.27).toFixed(2));
                                                                                                                                                                                        };
                                                                                                                                                                                          const commitRiser = () => {
                                                                                                                                                                                              const v = safeNum(riserStr, element.riserHeight ?? 0.17);
                                                                                                                                                                                                  if (v > 0) onUpdate(element.id, { riserHeight: v });
                                                                                                                                                                                                      else setRiserStr((element.riserHeight ?? 0.17).toFixed(2));
                                                                                                                                                                                                        };
                                                                                                                                                                                                          const commitElev = () => {
                                                                                                                                                                                                              const v = safeNum(elevStr, element.elevation ?? 0);
                                                                                                                                                                                                                  onUpdate(element.id, { elevation: v });
                                                                                                                                                                                                                    };
                                                                                                                                                                                                                      const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, commit: () => void) => {
                                                                                                                                                                                                                          if (e.key === 'Enter') {
                                                                                                                                                                                                                                commit();
                                                                                                                                                                                                                                      (e.target as HTMLInputElement).blur();
                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                              const stepCount = element.type === 'step' && element.treadDepth
                                                                                                                                                                                                                                                  ? Math.max(2, Math.floor(element.length / element.treadDepth))
                                                                                                                                                                                                                                                      : 0;
                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                            <div
                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                          display: 'flex',
                                                                                                                                                                                                                                                                                  gap: 10,
                                                                                                                                                                                                                                                                                          alignItems: 'center',
                                                                                                                                                                                                                                                                                                  padding: '8px 12px',
                                                                                                                                                                                                                                                                                                          background: '#f8f8f8',
                                                                                                                                                                                                                                                                                                                  borderRadius: 8,
                                                                                                                                                                                                                                                                                                                          margin: 8,
                                                                                                                                                                                                                                                                                                                                  flexWrap: 'wrap',
                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                  <span style={{ fontWeight: 700, color: '#003366' }}>{element.type === 'step' ? '🪜' : '🟨'}</span>
                                                                                                                                                                                                                                                                                                                                                        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                <span style={labelStyle}>الطول (م):</span>
                                                                                                                                                                                                                                                                                                                                                                        <input
                                                                                                                                                                                                                                                                                                                                                                                  type="text"
                                                                                                                                                                                                                                                                                                                                                                                            inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                      dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                value={lengthStr}
                                                                                                                                                                                                                                                                                                                                                                                                                          style={inputStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                                    onFocus={e => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={e => setLengthStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                        onBlur={commitLength}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onKeyDown={e => handleKeyDown(e, commitLength)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <span style={labelStyle}>العرض (م):</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value={widthStr}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={inputStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onFocus={e => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={e => setWidthStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onBlur={commitWidth}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onKeyDown={e => handleKeyDown(e, commitWidth)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span style={{ ...labelStyle, color: '#b35900' }}>المنسوب (م):</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={elevStr}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{ ...inputStyle, background: '#fff8e1', borderColor: '#f5a623' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onFocus={e => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={e => setElevStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onBlur={commitElev}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onKeyDown={e => handleKeyDown(e, commitElev)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {element.type === 'step' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span style={labelStyle}>عمق الدرجة:</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={treadStr}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={inputStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onFocus={e => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={e => setTreadStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onBlur={commitTread}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onKeyDown={e => handleKeyDown(e, commitTread)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span style={labelStyle}>ارتفاع الدرجة:</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={riserStr}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={inputStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onFocus={e => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={e => setRiserStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onBlur={commitRiser}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onKeyDown={e => handleKeyDown(e, commitRiser)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ fontSize: 12, color: '#555', fontWeight: 700 }}>🔢 {stepCount} درجة</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => onRotate(element.id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: '6px 12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: '#f80',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      borderRadius: 6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                🔄 90°
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => onUpdate(element.id, { locked: !element.locked })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title={element.locked ? 'إلغاء القفل' : 'قفل العنصر'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: '6px 12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: element.locked ? '#e67e22' : '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: element.locked ? '#fff' : '#e67e22',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: '2px solid #e67e22',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      borderRadius: 6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {element.locked ? '🔓' : '🔒'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => onDelete(element.id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: '6px 12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: '#dc3545',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              borderRadius: 6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        🗑️
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };